<template><AppLayout><TablePageLayout><template #filters><div class="space-y-3"><div class="flex flex-wrap justify-between gap-4"><div><h1 class="text-2xl font-semibold">{{ t('adminMarketplace.reconciliation') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('adminMarketplace.reconciliationHint') }}</p></div><div class="flex flex-wrap gap-2"><button data-test="open-funding-tools" class="btn btn-secondary" @click="fundingToolsOpen = true">{{ t('adminFundingTools.title') }}</button><button class="btn btn-secondary" @click="incidentOpen = true">{{ t('adminMarketplace.executionIncident') }}</button><button class="btn btn-secondary" @click="openTool('migrate')">{{ t('adminMarketplace.migrate') }}</button><button class="btn btn-secondary" @click="openTool('statement')">{{ t('adminMarketplace.statement') }}</button><button class="btn btn-secondary" :disabled="loading" @click="load">{{ t('common.refresh') }}</button></div></div><form class="flex flex-wrap items-end gap-3" @submit.prevent="lookupReceipt"><label class="text-sm">{{ t('adminMarketplace.incidentReceipt') }}<input v-model.trim="receiptId" data-test="receipt-id" class="input mt-1" autocomplete="off" @input="receiptDetail = null" /></label><button data-test="lookup-receipt" class="btn btn-secondary" :disabled="busy || !validReceiptId">{{ t('adminMarketplace.lookupReceipt') }}</button></form><div v-if="receiptDetail" class="rounded border p-3 text-sm"><p>{{ receiptDetail.receipt_id }} · {{ receiptDetail.status }} · {{ receiptDetail.capture_status }}</p><p>{{ t('adminMarketplace.capturedAmount') }}: {{ receiptDetail.captured }} USD · {{ t('adminMarketplace.refundedAmount') }}: {{ receiptDetail.refunded_amount }} USD · {{ t('adminMarketplace.refundableAmount') }}: {{ receiptDetail.refundable_amount }} USD</p><button data-test="refund-loaded" class="btn btn-secondary btn-sm mt-2" :disabled="!['pending','matured'].includes(receiptDetail.capture_status)" @click="openReceipt({ kind: 'receipt', id: receiptDetail.receipt_id, status: receiptDetail.status, age_seconds: 0 }, 'refund')">{{ t('adminMarketplace.refund') }}</button></div><form class="flex flex-wrap items-end gap-3" @submit.prevent="page = 1; load()"><label class="text-sm">{{ t('adminMarketplace.statusFilter') }}<input v-model="statusFilter" class="input mt-1" /></label><button class="btn btn-secondary" type="submit">{{ t('adminMarketplace.filter') }}</button></form><div v-if="totals" class="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5"><StatCard v-for="field in totalFields" :key="field" :title="t(`adminMarketplace.${field}`)" :value="totals[field]" /></div><p v-if="totals" class="text-sm text-gray-500">{{ t('adminMarketplace.receiptStatuses') }}: <span v-for="(count, status) in totals.receipt_statuses" :key="status" class="mr-3">{{ status }}: {{ count }}</span></p><p v-if="error" role="alert" class="text-red-600">{{ error }} <button class="underline" @click="load">{{ t('adminMarketplace.retry') }}</button></p></div></template><template #table><DataTable :columns="columns" :data="rows" :loading="loading"><template #cell-actions="{ row }"><div v-if="row.kind === 'receipt'" class="flex flex-wrap gap-2"><button class="btn btn-secondary btn-sm" @click="openReceipt(row, 'reconcile')">{{ t('adminMarketplace.reconcile') }}</button></div></template></DataTable></template><template #pagination><Pagination v-if="total > 20" :page="page" :page-size="20" :total="total" @update:page="changePage" /></template></TablePageLayout>
<BaseDialog :show="!!tool" :title="t(`adminMarketplace.${tool || 'reconcile'}`)" @close="close"><div class="space-y-4"><p v-if="tool === 'migrate'">{{ t('adminMarketplace.migrateConfirm') }}</p><p v-if="tool === 'reconcile'" class="rounded-lg bg-amber-50 p-3 text-sm text-amber-900 dark:bg-amber-900/20 dark:text-amber-200">{{ t('adminMarketplace.receiptWarning') }}</p><p v-if="attempted" class="text-sm text-amber-700 dark:text-amber-300">{{ t('adminMarketplace.retrySame') }} <span v-if="tool === 'refund' && receipt" class="break-all">{{ t('marketplace.operationReference') }}: {{ operations.get(`refund:${receipt.id}`)?.key }}</span> <button v-if="receipt" class="underline" :disabled="busy" @click="checkReceipt">{{ t('adminMarketplace.checkStatus') }}</button></p><p v-if="receipt">{{ t('adminMarketplace.receipt') }}: {{ receipt.id }} · {{ receipt.status }}</p><label v-if="tool === 'reconcile'" class="block">{{ t('adminMarketplace.decision') }}<select v-model="form.action" :disabled="attempted" class="input mt-1"><option value="release_confirmed_unexecuted">{{ t('adminMarketplace.release_confirmed_unexecuted') }}</option><option value="retry_known_usage">{{ t('adminMarketplace.retry_known_usage') }}</option></select></label><label v-if="tool === 'refund'" class="block">{{ t('adminMarketplace.amount') }} (USD)<input v-model="form.amount" class="input mt-1" inputmode="decimal" :disabled="attempted && !refundReentry" /></label><label v-if="tool === 'migrate' || tool === 'statement'" class="block">{{ t('adminMarketplace.userId') }}<input v-model="form.userId" class="input mt-1" inputmode="numeric" :disabled="attempted" /></label><label v-if="tool === 'statement'" class="block">{{ t('adminMarketplace.month') }} (UTC)<input v-model="form.month" type="month" class="input mt-1" :disabled="attempted" /></label><label v-if="tool !== 'migrate'" class="block">{{ t('adminMarketplace.reason') }}<textarea v-model="form.reason" class="input mt-1" rows="3" :disabled="attempted && !refundReentry" /></label><p v-if="dialogError" role="alert" class="text-red-600">{{ dialogError }}</p><div v-if="result" role="status" class="text-sm text-primary-700 dark:text-primary-300"><p>{{ t('adminMarketplace.completed') }}</p><dl v-if="tool === 'migrate'" class="mt-2 grid grid-cols-2 gap-2"><template v-for="field in migrationFields" :key="field"><dt>{{ t(`adminMarketplace.${field}`) }}</dt><dd>{{ result[field] }}</dd></template></dl></div></div><template #footer><button class="btn btn-secondary" :disabled="busy" @click="close">{{ t('common.close') }}</button><button class="btn btn-primary" :disabled="busy || !!result || !valid || (attempted && !!receipt && !statusChecked)" @click="submit">{{ attempted ? t('adminMarketplace.retryAction') : t('adminMarketplace.confirmAction') }}</button></template></BaseDialog><TotpStepUpDialog :controller="stepUp" /><ExecutionIncidentDialog :show="incidentOpen" @close="incidentOpen = false" /><FundingAdminToolsDialog :show="fundingToolsOpen" @close="fundingToolsOpen = false" /></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TablePageLayout from '@/components/layout/TablePageLayout.vue'
import DataTable from '@/components/common/DataTable.vue'
import StatCard from '@/components/common/StatCard.vue'
import Pagination from '@/components/common/Pagination.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useAuthStore } from '@/stores/auth'
import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
import { reconciliation, get, post, type Receipt, type ReceiptDetail, type ReconciliationTotals } from '@/api/admin/marketplace'
import ExecutionIncidentDialog from '@/components/marketplace/ExecutionIncidentDialog.vue'
import FundingAdminToolsDialog from '@/components/admin/FundingAdminToolsDialog.vue'
import { validPrice } from './adminState'
const { t } = useI18n(), stepUp = useStepUp(), auth = useAuthStore()
const incidentOpen = ref(false); const fundingToolsOpen = ref(false)
const receiptId = ref(''); const receiptDetail = ref<ReceiptDetail | null>(null); const validReceiptId = computed(() => /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(receiptId.value)); let lookupGeneration = 0
async function lookupReceipt() { if (!validReceiptId.value || busy.value || !auth.user) return; const id = receiptId.value, actor = auth.user.id, generation = ++lookupGeneration; const active = () => generation === lookupGeneration && auth.user?.id === actor && receiptId.value === id; busy.value = true; error.value = ''; receiptDetail.value = null; try { const result = await stepUp.run(() => active() ? get<ReceiptDetail>(`receipts/${id}`) : Promise.reject(new Error('Lookup cancelled'))); if (active()) receiptDetail.value = result } catch (e: any) { if (active() && !isStepUpCancelled(e)) error.value = e?.message || t('adminMarketplace.loadError') } finally { if (active()) busy.value = false } }
const loading = ref(false), busy = ref(false), error = ref(''), dialogError = ref(''), result = ref<Record<string, any> | null>(null), statusFilter = ref(''), totals = ref<ReconciliationTotals | null>(null), page = ref(1), total = ref(0), rows = ref<Receipt[]>([])
const receipt = ref<Receipt | null>(null), tool = ref(''), attempted = ref(false), statusChecked = ref(false), form = ref({ action: 'release_confirmed_unexecuted', amount: '', userId: '', month: '', reason: '' })
type Operation = { key: string; body?: any; path: string; salt?: string; digest?: string }
const operations = new Map<string, Operation>(); let actionGeneration = 0, listGeneration = 0
watch(() => auth.user?.id, id => { actionGeneration++; lookupGeneration++; listGeneration++; operations.clear(); tool.value = ''; receipt.value = null; receiptId.value = ''; receiptDetail.value = null; result.value = null; form.value = { action: 'release_confirmed_unexecuted', amount: '', userId: '', month: '', reason: '' }; rows.value = []; totals.value = null; total.value = 0; busy.value = false; loading.value = false; if (id) void load() }, { flush: 'sync' })
function refundStorage(id: string) { return `admin-marketplace-refund:${auth.user?.id}:${id}` }
function savedRefund(id: string): Operation | null { try { const key = refundStorage(id); const op = JSON.parse(sessionStorage.getItem(key) || 'null'); if (!op || typeof op.key !== 'string') return null; if (typeof op.salt === 'string' && typeof op.digest === 'string') return { key: op.key, salt: op.salt, digest: op.digest, path: `receipts/${id}/refund` }; if (op.body) { const legacy = { key: op.key, salt: '', digest: 'legacy', path: `receipts/${id}/refund` }; sessionStorage.setItem(key, JSON.stringify({ key: legacy.key, salt: legacy.salt, digest: legacy.digest })); return legacy } return null } catch { return null } }
async function fingerprint(body: unknown, salt: string) { const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`${salt}\0${JSON.stringify(body)}`)); return Array.from(new Uint8Array(hash), x => x.toString(16).padStart(2, '0')).join('') }
const refundReentry = computed(() => tool.value === 'refund' && !!receipt.value && attempted.value && operations.get(`refund:${receipt.value.id}`)?.body === undefined)
const columns = computed(() => ['kind', 'id', 'status', 'difference', 'age_seconds', 'actions'].map(key => ({ key, label: t(`adminMarketplace.${key}`) })))
const valid = computed(() => tool.value === 'migrate' ? /^[1-9]\d*$/.test(form.value.userId) : !!form.value.reason.trim() && (tool.value !== 'refund' || validPrice(form.value.amount)) && (tool.value !== 'statement' || (/^[1-9]\d*$/.test(form.value.userId) && /^\d{4}-(0[1-9]|1[0-2])$/.test(form.value.month))))
const totalFields = ['unbalanced_transactions', 'wallet_differences', 'funding_differences', 'buyer_ledger_differences', 'aged_outbox', 'uncertain_payouts', 'cache_backlog', 'cache_oldest_age_seconds', 'maturity_backlog', 'maturity_oldest_age_seconds', 'maturity_failures', 'maturity_oldest_failure_age_seconds'] as const
const migrationFields = ['currency', 'eligible_available', 'reserved', 'excluded_available', 'debt', 'migrated', 'reconciled'] as const
async function load() { if (!auth.user) return; const actor = auth.user.id, generation = ++listGeneration; loading.value = true; error.value = ''; try { const value = await reconciliation(page.value, statusFilter.value); if (generation !== listGeneration || auth.user?.id !== actor) return; rows.value = value.items; total.value = value.total; totals.value = value.totals } catch (e: any) { if (generation === listGeneration && auth.user?.id === actor) error.value = e?.message || t('adminMarketplace.loadError') } finally { if (generation === listGeneration && auth.user?.id === actor) loading.value = false } }
function changePage(next: number) { page.value = next; void load() }
async function checkReceipt() { if (!receipt.value || !auth.user) return; const id = receipt.value.id, initialStatus = receipt.value.status, selectedTool = tool.value, actor = auth.user.id, generation = actionGeneration; const active = () => generation === actionGeneration && auth.user?.id === actor && receipt.value?.id === id && tool.value === selectedTool; busy.value = true; dialogError.value = ''; try { if (selectedTool === 'refund') { const fresh = await stepUp.run(() => active() ? get<ReceiptDetail>(`receipts/${id}`) : Promise.reject(new Error('Lookup cancelled'))); if (active()) { receiptDetail.value = fresh; statusChecked.value = true } return } const current = await reconciliation(page.value, statusFilter.value); if (!active()) return; const found = current.items.find(row => row.kind === 'receipt' && row.id === id); if (!found || found.status !== initialStatus) { dialogError.value = t('adminMarketplace.receiptChanged'); return } statusChecked.value = true; rows.value = current.items; totals.value = current.totals; total.value = current.total } catch (e: any) { if (active() && !isStepUpCancelled(e)) dialogError.value = e?.message || t('adminMarketplace.loadError') } finally { if (active()) busy.value = false } }
function openReceipt(row: Receipt, next: string) { receipt.value = row; openTool(next) }
function openTool(next: string) { tool.value = next; dialogError.value = ''; result.value = null; form.value = { action: 'release_confirmed_unexecuted', amount: '', userId: '', month: '', reason: '' }; const op = operations.get(`${next}:${receipt.value?.id || ''}`) || (next === 'refund' && receipt.value ? savedRefund(receipt.value.id) : null); if (op) operations.set(`${next}:${receipt.value?.id || ''}`, op); attempted.value = !!op; statusChecked.value = false; if (op?.body) { const b = op.body; form.value = { action: b.action || 'release_confirmed_unexecuted', amount: b.amount || '', userId: b.supplier_id ? String(b.supplier_id) : op.path.match(/wallets\/(\d+)/)?.[1] || '', month: b.month || '', reason: b.reason || '' } } }
function close() { actionGeneration++; tool.value = ''; receipt.value = null; dialogError.value = '' }
async function submit() {
  if (!valid.value || busy.value || result.value || !auth.user) return
  const actor = auth.user.id, generation = actionGeneration, selectedTool = tool.value, selectedReceipt = receipt.value?.id || ''
  const operationId = `${selectedTool}:${selectedReceipt}`; let op = operations.get(operationId); const wasPending = !!op
  const body = selectedTool === 'reconcile' ? { action: form.value.action, reason: form.value.reason.trim() } : selectedTool === 'refund' ? { amount: form.value.amount, reason: form.value.reason.trim() } : selectedTool === 'statement' ? { supplier_id: Number(form.value.userId), month: form.value.month, reason: form.value.reason.trim() } : {}
  const path = selectedTool === 'migrate' ? `wallets/${form.value.userId}/migrate` : selectedTool === 'statement' ? 'statements/generate' : `receipts/${selectedReceipt}/${selectedTool}`
  const storageKey = selectedTool === 'refund' && selectedReceipt ? refundStorage(selectedReceipt) : '', active = () => generation === actionGeneration && auth.user?.id === actor
  busy.value = true; dialogError.value = ''
  try {
    if (!op) { if (storageKey) { const salt = crypto.randomUUID(); op = { key: crypto.randomUUID(), body, path, salt, digest: await fingerprint(body, salt) }; if (!active()) return; sessionStorage.setItem(storageKey, JSON.stringify({ key: op.key, salt: op.salt, digest: op.digest })) } else op = { key: crypto.randomUUID(), body, path }; operations.set(operationId, op) }
    else if (storageKey && (!op.salt || !op.digest || await fingerprint(body, op.salt) !== op.digest)) { if (active()) dialogError.value = t('adminMarketplace.retryPayloadMismatch'); return }
    if (!active()) return
    const operation = op; attempted.value = true; statusChecked.value = false
    const response = await stepUp.run(() => active() ? post(operation.path, storageKey ? body : operation.body, operation.key) : Promise.reject(new Error('Action cancelled')))
    if (operations.get(operationId) === operation) operations.delete(operationId); if (storageKey) { const saved = JSON.parse(sessionStorage.getItem(storageKey) || 'null'); if (saved?.key === operation.key) sessionStorage.removeItem(storageKey) }
    if (!active()) return; attempted.value = false; result.value = typeof response === 'object' && response ? response as Record<string, any> : {}; await load()
  } catch (e: any) { if (isStepUpCancelled(e) && !wasPending && op) { if (operations.get(operationId) === op) operations.delete(operationId); if (storageKey) sessionStorage.removeItem(storageKey); if (active()) attempted.value = false } else if (active() && !isStepUpCancelled(e)) dialogError.value = e?.message || t('adminMarketplace.actionError') } finally { if (active()) busy.value = false }
}

onMounted(load); onUnmounted(() => { actionGeneration++; lookupGeneration++; listGeneration++ })
</script>
